/**
 * Align `base` and `side` on a longest common subsequence of whole lines.
 * Ties are broken towards matches that come earliest: walking both documents
 * from the start we take a match whenever the current lines are equal, and
 * otherwise advance the side whose remaining subsequence is at least as long
 * as the other's, preferring to advance the base when they tie.
 *
 * @param {string[]} base
 * @param {string[]} side
 * @returns {Array<[number, number]>} matched (base index, side index) pairs
 */
export function align(base, side) {
  const n = base.length
  const m = side.length
  // lcs[i * (m + 1) + j] is the length of the LCS of base[i..] and side[j..].
  const lcs = new Int32Array((n + 1) * (m + 1))
  for (let i = n - 1; i >= 0; i -= 1) {
    for (let j = m - 1; j >= 0; j -= 1) {
      const here = i * (m + 1) + j
      if (base[i] === side[j]) {
        lcs[here] = lcs[here + (m + 1) + 1] + 1
      } else {
        const dropBase = lcs[here + (m + 1)]
        const dropSide = lcs[here + 1]
        lcs[here] = dropBase >= dropSide ? dropBase : dropSide
      }
    }
  }

  const pairs = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      pairs.push([i, j])
      i += 1
      j += 1
    } else if (lcs[(i + 1) * (m + 1) + j] >= lcs[i * (m + 1) + j + 1]) {
      i += 1
    } else {
      j += 1
    }
  }
  return pairs
}

/**
 * @typedef {object} Change
 * @property {'mine' | 'theirs'} side
 * @property {number} baseStart
 * @property {number} baseEnd
 * @property {number} sideStart
 * @property {number} sideEnd
 */

/**
 * Every stretch the common subsequence does not cover, as a run of base lines
 * replaced by a run of the side's lines.
 *
 * @param {string[]} base
 * @param {string[]} side
 * @param {'mine' | 'theirs'} name
 * @returns {Change[]}
 */
export function changes(base, side, name) {
  const pairs = align(base, side)
  const out = []
  let i = 0
  let j = 0
  const emit = (baseEnd, sideEnd) => {
    if (baseEnd > i || sideEnd > j) {
      out.push({ side: name, baseStart: i, baseEnd, sideStart: j, sideEnd })
    }
  }
  for (const [bi, si] of pairs) {
    emit(bi, si)
    i = bi + 1
    j = si + 1
  }
  emit(base.length, side.length)
  return out
}
"}

