 * The three-way merge itself: gather both sides' changes into regions and
 * resolve each one.
 */

import { changes } from './diff.js'

/**
 * @typedef {object} Region
 * @property {'stable' | 'mine' | 'theirs' | 'both' | 'conflict'} kind
 * @property {string[]} lines resolved lines (empty for a conflict)
 * @property {string[]} mine
 * @property {string[]} base
 * @property {string[]} theirs
 */

/**
 * Split the three documents into stable and changed regions.
 *
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 * @returns {Region[]}
 */
export function merge(mine, base, theirs) {
  const all = [...changes(base, mine, 'mine'), ...changes(base, theirs, 'theirs')]
  // Ordered by where they start in the base, mine before theirs on a tie; the
  // sort is stable so listing mine's changes first is enough.
  all.sort((a, b) => a.baseStart - b.baseStart)

  const docs = { mine, theirs }
  const regions = []
  let cursor = 0
  let index = 0
  while (index < all.length) {
    const group = [all[index]]
    let start = all[index].baseStart
    let end = all[index].baseEnd
    index += 1
    while (index < all.length && all[index].baseStart <= end) {
      group.push(all[index])
      if (all[index].baseEnd > end) end = all[index].baseEnd
      index += 1
    }

    if (start > cursor) {
      regions.push(stable(base.slice(cursor, start)))
    }
    cursor = end

    const baseLines = base.slice(start, end)
    const sides = {}
    for (const name of ['mine', 'theirs']) {
      const own = group.filter(change => change.side === name)
      if (own.length === 0) {
        sides[name] = baseLines
        continue
      }
      let lo = Infinity
      let hi = -Infinity
      let ownStart = Infinity
      let ownEnd = -Infinity
      for (const change of own) {
        if (change.sideStart < lo) lo = change.sideStart
        if (change.sideEnd > hi) hi = change.sideEnd
        if (change.baseStart < ownStart) ownStart = change.baseStart
        if (change.baseEnd > ownEnd) ownEnd = change.baseEnd
      }
      sides[name] = docs[name].slice(lo - (ownStart - start), hi + (end - ownEnd))
    }

    regions.push(resolve(sides.mine, baseLines, sides.theirs))
  }

  if (cursor < base.length) {
    regions.push(stable(base.slice(cursor)))
  }
  return regions
}

/**
 * @param {string[]} lines
 * @returns {Region}
 */
function stable(lines) {
  return { kind: 'stable', lines, mine: lines, base: lines, theirs: lines }
}

/**
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 * @returns {Region}
 */
function resolve(mine, base, theirs) {
  if (same(mine, theirs)) return { kind: 'both', lines: mine, mine, base, theirs }
  if (same(mine, base)) return { kind: 'theirs', lines: theirs, mine, base, theirs }
  if (same(theirs, base)) return { kind: 'mine', lines: mine, mine, base, theirs }
  return { kind: 'conflict', lines: [], mine, base, theirs }
}

/**
 * @param {string[]} a
 * @param {string[]} b
 * @returns {boolean}
 */
function same(a, b) {
  return a.length === b.length && a.every((line, i) => line === b[i])
}
"}

